import java.util.*;
import java.io.*;

public class Main {
    static class FastIO {
        private final int BUFFER_SIZE = 1 << 21;
        private final byte[] buffer = new byte[BUFFER_SIZE];
        private int bufferPointer = 0, bytesRead = 0;
        private final InputStream in = System.in;
        private final OutputStream out = System.out;
        private final StringBuilder stringBuilder = new StringBuilder();

        public FastIO() { }

        private byte read() {
            if (bytesRead == -1) return -1;
            if (bufferPointer >= bytesRead) {
                try {
                    bytesRead = in.read(buffer);
                } catch (IOException e) {
                    bytesRead = -1;
                }
                if (bytesRead == -1) return -1;
                bufferPointer = 0;
            }
            return buffer[bufferPointer++];
        }

        public int nextInt() {
            int c = read();
            while (c != -1 && (c < 48 || c > 57)) {
                if (c == -1) return -1;
                c = read();
            }
            if (c == -1) return -1;
            int X = 0;
            boolean negative = false;
            while (true) {
                if (c == '-') {
                    negative = true;
                    c = read();
                } else if (c >= 48 && c <= 57) {
                    X = X * 10 + (c ^ 48);
                    c = read();
                } else break;
            }
            if (negative) X = ~ (X - 1);
            return X;
        }

        public long nextLong() {
            int c = read();
            while (c != -1 && (c < 48 || c > 57)) {
                if (c == -1) return -1;
                c = read();
            }
            if (c == -1) return -1;
            long X = 0;
            boolean negative = false;
            while (true) {
                if (c == '-') {
                    negative = true;
                    c = read();
                } else if (c >= 48 && c <= 57) {
                    X = X * 10 + (c ^ 48);
                    c = read();
                } else break;
            }
            if (negative) X = ~ (X - 1);
            return X;
        }

        public String nextString() {
            StringBuilder sb = new StringBuilder();
            int c = read();
            while (c != -1 && c < 33) {
                c = read();
            }
            while (c != -1 && c > 32) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        public void print(String s) throws IOException {
            for (int i = 0; i < s.length(); i++) {
                out.write(s.charAt(i));
            }
        }

        public void print(char ch) throws IOException {
            out.write(ch);
        }

        public void flush() throws IOException {
            out.flush();
        }
    }

    static final long[] p = {1,10,100,1000,10000,100000,1000000,10000000};
    static final int M = 998244353;
    static final int M2 = 1000000007;

    static int idx, ans;
    static long n, Idx = -1;
    static long[] s = new long[10];
    static int[][] v = new int[10][];
    static int[] L = new int[10];

    static boolean F_ = false;

    static int Del(int x) {
        return x >= M ? x - M : x;
    }

    static int Del1(int x) {
        return x >= M2 ? x - M2 : x;
    }

    static List<int[]> vLists = new ArrayList<>();

    public static void dfs1(int x, int d) {
        int u = Del(idx - x + M);
        v[d] = ensureCapacity(v[d], L[d]);
        v[d][L[d]++] = u;
        idx++;
        s[d] += u;
        if (d == 6) return;
        for (int i = 0; i <= 9; i++) {
            dfs1(x * 10 + i, d + 1);
        }
    }

    public static void query(long x, long r, int[] vArr, int LVal, long[] sArr) {
        for (int i = 0; i <= 6; i++) {
            long t = (r - x * p[i]) % M;
            if (t < 0) t += M;
            int g = lowerBound(vArr, 0, LVal, (int) (M - t));
            ans = (int) (Del1(ans + sArr[i] + t * LVal - (long) M * (LVal - g)));
        }
    }

    public static void dfs2(long x, long n) {
        if ((x + 1) * p[6] <= n + 1 && x * p[7] > n) {
            query(x, Idx + 1, v[idx], L[idx], s);
            Idx += idx;
            return;
        }
        Idx++;
        ans = Del1(ans + Del((int)((Idx - x) % M + M)));
        for (int i = 0; i <= (x == 0 ? 0 : 9); i++) {
            if (x * 10 + i <= n) {
                dfs2(x * 10 + i, n);
            }
        }
    }

    public static int lowerBound(int[] arr, int start, int end, int key) {
        int low = start, high = end;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (arr[mid] < key) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    public static int[] ensureCapacity(int[] arr, int size) {
        if (arr == null || arr.length < size) {
            return new int[Math.max(arr == null ? 0 : arr.length * 2, size)];
        }
        return arr;
    }

    public static void main(String[] args) throws IOException {
        FastIO io = new FastIO();

        // Initialize v arrays for each digit length
        for (int i = 0; i <= 6; i++) {
            v[i] = new int[1000005];
        }

        // Run dfs1 to populate v and s
        idx = 0;
        dfs1(0, 0);

        n = io.nextLong();
        ans = 0;
        dfs2(0, n);
        io.print(String.valueOf(ans));
        io.flush();
    }
}
